use clap::{Arg, ArgAction, Command};
use std::io::Read;

fn build_cli() -> Command {
    Command::new("flamelens")
        .version("0.3.1")
        .arg(
            Arg::new("FILENAME")
                .help("Profile data filename")
        )
        .arg(
            Arg::new("sorted")
                .long("sorted")
                .action(ArgAction::SetTrue)
                .help("Whether to sort the stacks by time spent")
        )
        .arg(
            Arg::new("echo")
                .long("echo")
                .action(ArgAction::SetTrue)
                .help("Print data to stdout on exit. Useful when piping to other tools")
        )
        .arg(
            Arg::new("debug")
                .long("debug")
                .action(ArgAction::SetTrue)
                .help("Show debug info")
        )
}

fn main() -> Result<(), std::io::Error> {
    let matches = build_cli().get_matches();
    let filename: Option<String> = matches.get_one::<String>("FILENAME").cloned();
    let sorted = matches.get_flag("sorted");
    let echo = matches.get_flag("echo");
    let debug = matches.get_flag("debug");
    let _ = (sorted, echo, debug);
    let (data, _display): (String, String) = if let Some(f) = filename {
