{"command":"cat <<'RS' > src/app.rs
use std::collections::{HashMap, HashSet};
use regex::Regex;

#[derive(Debug, Clone)]
pub struct Stack {
    pub frames: Vec<String>,
    pub count: u64,
}

pub fn parse_folded(data: &str) -> (Vec<Stack>, u64) {
    let mut stacks = Vec::new();
    let mut total = 0u64;
    for line in data.split('\n') {
        // line may contain \r? keep it (split('\n') keeps \r), so count with \r fails
        if line.is_empty() {
            continue;
        }
        // rsplit_once(' ')
        let Some((stack_part, count_part)) = line.rsplit_once(' ') else {
            continue;
        };
        if stack_part.is_empty() {
            continue;
        }
        let Ok(count) = count_part.parse::<u64>() else {
            continue;
        };
        // count 0 is stored? yes, but total unchanged? still store for Top?
        // split stack by ';' keeping empty
        let frames: Vec<String> = stack_part.split(';').map(|s| s.to_string()).collect();
        total = total.wrapping_add(count);
        stacks.push(Stack { frames, count });
    }
    (stacks, total)
}

#[derive(Debug, Clone)]
pub struct Node {
    pub name: String,
    pub total: u64,
    pub children: Vec<Node>,
    pub full_stack: String,
}

impl Node {
    pub fn new(name: String, full_stack: String) -> Self {
        Node { name, total: 0, children: Vec::new(), full_stack }
    }
}

pub fn build_tree(stacks: &[Stack], sorted: bool) -> Node {
    let mut root = Node::new("all".to_string(), "all".to_string());
    let mut total = 0u64;
    for stack in stacks {
        total = total.wrapping_add(stack.count);
        // insert
        let mut current = &mut root;
        current.total = current.total.wrapping_add(stack.count);
        let mut prefix_parts: Vec<String> = Vec::new();
        for frame in &stack.frames {
            prefix_parts.push(frame.clone());
            let full = prefix_parts.join(";");
            // find child with same name? Need to distinguish by full stack? Since same name under same parent with same full stack should merge.
            // Children are distinguished by name? For same parent, same frame name means same full stack (since parent prefix same), so merge by name.
            // Find child index by name
            let mut found_idx: Option<usize> = None;
            for (i, child) in current.children.iter().enumerate() {
                if child.name == *frame {
                    found_idx = Some(i);
                    break;
                }
            }
            if let Some(idx) = found_idx {
                current.children[idx].total = current.children[idx].total.wrapping_add(stack.count);
                // move to child: need to get mutable ref again (borrow checker workaround via index)
                // Use raw pointer? Simpler: use iterative with indices path? Instead, we can re-borrow via loop with split?
                // Workaround: use unsafe or restructure: we'll navigate via &mut through loop using indexes
                // To avoid borrow issues, we do: current = &mut current.children[idx] via re-borrow (need to end previous borrow)
                // This is allowed with NLL? current is &mut, current.children[idx] is &mut, should work.
                // But we have immutable borrow in loop above (current.children.iter()). Need to end it before mutable.
                // So we already ended (found_idx computed), now mutable.
                // However Rust still holds? Let's do it via position then get_mut
                let child = &mut current.children[idx];
                // update full_stack? already same
                current = child;
            } else {
                let mut new_node = Node::new(frame.clone(), full);
                new_node.total = stack.count;
                current.children.push(new_node);
                let len = current.children.len();
                current = &mut current.children[len - 1];
            }
        }
    }
    root.total = total;
    // For root, full_stack is "all"? Keep as "all" for color? Root color fixed anyway.
    if sorted {
        sort_tree(&mut root);
    }
    root
}

fn sort_tree(node: &mut Node) {
    // sort ascending stable by total, then reverse to get descending with ties reversed (as observed)
    node.children.sort_by(|a, b| a.total.cmp(&b.total));
    node.children.reverse();
    for child in &mut node.children {
        sort_tree(child);
    }
}

#[derive(Debug, Clone)]
pub struct FuncStat {
    pub total: u64,
    pub own: u64,
}

pub fn build_func_stats(stacks: &[Stack]) -> HashMap<String, FuncStat> {
    let mut map: HashMap<String, FuncStat> = HashMap::new();
    for stack in stacks {
        let mut seen: HashSet<&String> = HashSet::new();
        for frame in &stack.frames {
            if seen.insert(frame) {
                let entry = map.entry(frame.clone()).or_insert(FuncStat { total: 0, own: 0 });
                entry.total = entry.total.wrapping_add(stack.count);
            }
        }
        if let Some(leaf) = stack.frames.last() {
            let entry = map.entry(leaf.clone()).or_insert(FuncStat { total: 0, own: 0 });
            // Note: total already added above (since leaf in seen), now add own
            entry.own = entry.own.wrapping_add(stack.count);
        }
    }
    map
}

// Color generation: single param t from hash of full_stack
// Use FNV-1a hash? Need deterministic. We'll use std DefaultHasher? But need to match original? We'll use simple hash and linear mapping.
pub fn frame_color(full_stack: &str) -> (u8, u8, u8) {
    // Special case root "all" -> reddest (205,3,0) to match observed
    if full_stack == "all" {
        return (205, 3, 0);
    }
    // FNV-1a 64-bit
    let mut h: u64 = 14695981039346656037;
    for b in full_stack.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(1099511628211);
    }
    // Map to t in [0,1): use lower bits? Use h % 1000 / 1000.0 ?
    // To get distribution similar to observed, use h % 1000
    let t = ((h % 1000) as f64) / 1000.0;
    // Also mix upper bits? Use (h >> 32) % 1000? Combine?
    // For better distribution, use (h % 100000) / 100000?
    // Let's use h as f64 / u64::MAX for continuous
    // But to be deterministic and match collisions? We'll use h % 1000 for now, gives 1000 distinct t values, ~1000 distinct colors, collisions among 30 with 1000 possibilities: expected 435/1000=0.43, but observed 2 collisions, so 1000 too large. Use smaller N like 200?
    // Let's use h % 200 / 200.0? Then 200 distinct, expected collisions 2.17 matches observed 2. Good.
    // But our earlier t from FNV%50 didn't match R. Let's try different: use h % 256?
    // For now, use continuous: t = (h as f64) / (u64::MAX as f64)
    // Then R=205+round(49*t), G=3+round(226*t), B=round(54*t)
    // This gives continuous, ~200 distinct after rounding? Let's use this.
    let t_cont = (h as f64) / (u64::MAX as f64);
    let r = (205.0 + 49.0 * t_cont).round() as u8;
    let g = (3.0 + 226.0 * t_cont).round() as u8;
    let b = (54.0 * t_cont).round() as u8;
    // Clamp? round may give 205..254, 3..229, 0..54. Good.
    (r, g, b)
}

pub fn fg_for_bg(r: u8, g: u8, b: u8) -> (u8, u8, u8) {
    // luminance formula, threshold 135 (between 133.8 and 136.6 as observed)
    let lum = (r as u32 * 299 + g as u32 * 587 + b as u32 * 114) / 1000;
    if lum > 135 {
        (10, 10, 10) // black
    } else {
        (225, 225, 225) // white
    }
}

// Helper to compute match samples: unique stacks where any frame matches regex (excluding root? stacks don't include root, so just frames)
pub fn match_samples(stacks: &[Stack], regex: &Regex) -> u64 {
    let mut sum = 0u64;
    for stack in stacks {
        for frame in &stack.frames {
            if regex.is_match(frame) {
                sum = sum.wrapping_add(stack.count);
                break;
            }
        }
    }
    sum
}

// For Top filter, same as above (since Top filter is same regex on function names, but Match counts stacks containing matching function)
