use std::collections::{HashMap, HashSet};
use regex::Regex;
use std::time::{Duration, Instant};

#[derive(Debug, Clone)]
pub struct Stack {
    pub frames: Vec<String>,
    pub count: u64,
}

pub fn parse_folded(data: &str) -> (Vec<Stack>, u64) {
    let mut stacks = Vec::new();
    let mut total = 0u64;
    for line in data.split('\n') {
        if line.is_empty() {
            continue;
        }
        let Some((stack_part, count_part)) = line.rsplit_once(' ') else {
            continue;
        };
        if stack_part.is_empty() {
            continue;
        }
        let Ok(count) = count_part.parse::<u64>() else {
            continue;
        };
        let frames: Vec<String> = stack_part.split(';').map(|s| s.to_string()).collect();
        total = total.wrapping_add(count);
        stacks.push(Stack { frames, count });
    }
    (stacks, total)
}

#[derive(Debug, Clone)]
pub struct Node {
    pub name: String,
    pub total: u64,
    pub children: Vec<Node>,
    pub full_stack: String,
}

impl Node {
    pub fn new(name: String, full_stack: String) -> Self {
        Node { name, total: 0, children: Vec::new(), full_stack }
    }
    pub fn get_by_path(&self, path: &[usize]) -> &Node {
        let mut cur = self;
        for &idx in path {
            cur = &cur.children[idx];
        }
        cur
    }
    pub fn get_by_path_mut(&mut self, path: &[usize]) -> &mut Node {
        let mut cur = self;
        for &idx in path {
            cur = &mut cur.children[idx];
        }
        cur
    }
}

pub fn build_tree(stacks: &[Stack], sorted: bool) -> Node {
    let mut root = Node::new("all".to_string(), "all".to_string());
    let mut total = 0u64;
    for stack in stacks {
        total = total.wrapping_add(stack.count);
        let mut current = &mut root;
        current.total = current.total.wrapping_add(stack.count);
        let mut prefix_parts: Vec<String> = Vec::new();
        for frame in &stack.frames {
            prefix_parts.push(frame.clone());
            let full = prefix_parts.join(";");
            let mut found_idx: Option<usize> = None;
            for (i, child) in current.children.iter().enumerate() {
                if child.name == *frame {
                    found_idx = Some(i);
                    break;
                }
            }
            if let Some(idx) = found_idx {
                // need to avoid borrow issue: get idx first, then mut
                current.children[idx].total = current.children[idx].total.wrapping_add(stack.count);
                // reborrow
                let ptr = &mut current.children[idx] as *mut Node;
                // SAFETY: we have exclusive access via current, idx valid
                unsafe {
                    current = &mut *ptr;
                }
            } else {
                let mut new_node = Node::new(frame.clone(), full);
                new_node.total = stack.count;
                current.children.push(new_node);
                let len = current.children.len();
                let ptr = &mut current.children[len - 1] as *mut Node;
                unsafe {
                    current = &mut *ptr;
                }
            }
        }
    }
    root.total = total;
    if sorted {
        sort_tree(&mut root);
    }
    root
}

fn sort_tree(node: &mut Node) {
    node.children.sort_by(|a, b| a.total.cmp(&b.total));
    node.children.reverse();
    for child in &mut node.children {
        sort_tree(child);
    }
}

#[derive(Debug, Clone)]
pub struct FuncStat {
    pub total: u64,
    pub own: u64,
}

pub fn build_func_stats(stacks: &[Stack]) -> HashMap<String, FuncStat> {
    let mut map: HashMap<String, FuncStat> = HashMap::new();
    for stack in stacks {
        let mut seen: HashSet<&String> = HashSet::new();
        for frame in &stack.frames {
            if seen.insert(frame) {
                let entry = map.entry(frame.clone()).or_insert(FuncStat { total: 0, own: 0 });
                entry.total = entry.total.wrapping_add(stack.count);
            }
        }
        if let Some(leaf) = stack.frames.last() {
            let entry = map.entry(leaf.clone()).or_insert(FuncStat { total: 0, own: 0 });
            entry.own = entry.own.wrapping_add(stack.count);
        }
    }
    map
}

pub fn frame_color(full_stack: &str) -> (u8, u8, u8) {
    if full_stack == "all" {
        return (205, 3, 0);
    }
    let mut h: u64 = 14695981039346656037;
    for b in full_stack.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(1099511628211);
    }
    let t = (h as f64) / (u64::MAX as f64);
    let r = (205.0 + 49.0 * t).round() as u8;
    let g = (3.0 + 226.0 * t).round() as u8;
    let b = (54.0 * t).round() as u8;
    (r, g, b)
}

pub fn fg_for_bg(r: u8, g: u8, b: u8) -> (u8, u8, u8) {
    let lum = (r as u32 * 299 + g as u32 * 587 + b as u32 * 114) / 1000;
    if lum > 135 {
        (10, 10, 10)
    } else {
        (225, 225, 225)
    }
}

pub fn match_samples(stacks: &[Stack], regex: &Regex) -> u64 {
    let mut sum = 0u64;
    for stack in stacks {
        for frame in &stack.frames {
            if regex.is_match(frame) {
                sum = sum.wrapping_add(stack.count);
                break;
            }
        }
    }
    sum
}

