fn handle_event(app: &mut App, ev: Event) -> Result<bool, std::io::Error> {
    match ev {
        Event::Key(key) => {
            // Ctrl+C always quits (even in search input? Observed Ctrl+C in search input does nothing (ignored), not quit. Wait earlier Ctrl+C in search stayed in search, not quit. So Ctrl+C in search input should be ignored, not quit.
            // Check: in search input mode, Ctrl+C ignored? Our earlier test showed Ctrl+C in search stayed in search (did not quit). Good. So only quit on Ctrl+C when not in input.
            // Similarly q in search input types 'q', not quit.
            if app.in_search_input {
                return handle_search_input_key(app, key);
            }
            // Not in input
            // Check Ctrl+C (with any modifiers? KeyCode::Char('c') + CONTROL)
            if key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL) {
                return Ok(true);
            }
            // Also Ctrl+C may come as KeyCode::Char('c') with CONTROL, or KeyModifiers? Good.
            // Handle keys based on view
            match app.view {
