fn render_help_top(buf: &mut Buffer, x: u16, y: u16, w: usize, _app: &App) {
    // Top help: "[j/k: move cursor] [f/b: scroll] [1: sort by total] [2: sort by own] [/: filter] [r: reset] [tab: switch view] [q: quit]"
    // Same logic as Flame (centered if fits, else truncated with leading space)
    let segments: Vec<(&str, &str)> = vec![
        ("j/k", "move cursor"),
        ("f/b", "scroll"),
        ("1", "sort by total"),
        ("2", "sort by own"),
        ("/", "filter"),
        ("r", "reset"),
        ("tab", "switch view"),
        ("q", "quit"),
    ];
    let mut chars_styles: Vec<(char, Style)> = Vec::new();
    for (i, (key, desc)) in segments.iter().enumerate() {
        if i > 0 {
            chars_styles.push((' ', Style::default()));
        }
        chars_styles.push(('[', Style::default()));
        for ch in key.chars() {
            chars_styles.push((ch, Style::default().fg(Color::Indexed(3)).add_modifier(Modifier::BOLD)));
        }
        chars_styles.push((':', Style::default()));
        chars_styles.push((' ', Style::default()));
        for ch in desc.chars() {
            chars_styles.push((ch, Style::default()));
        }
        chars_styles.push((']', Style::default()));
    }
    let total_len = chars_styles.len();
    if total_len < w {
        let leading = (w - total_len + 1) / 2;
        for (idx, (ch, style)) in chars_styles.iter().enumerate() {
            let cx = x + leading as u16 + idx as u16;
            if cx < x + w as u16 {
                buf.set_string(cx, y, &ch.to_string(), *style);
            }
        }
    } else {
        buf.set_string(x, y, " ", Style::default());
        for idx in 0..(w-1).min(total_len) {
            let (ch, style) = &chars_styles[idx];
            buf.set_string(x+1+idx as u16, y, &ch.to_string(), *style);
        }
    }
}

